1	// SPDX-FileCopyrightText: 2026 Chili.CHIPS*ba
2	//
3	// SPDX-License-Identifier: BSD-3-Clause
4	
5	//==========================================================================
6	// Description:
7	//   VProc main program to instantiate and run the rv32 RISC-V instruction
8	//   set simulator, with configuration via vusermain.cfg file.
9	//==========================================================================
10	
11	#include <cstdio>
12	#include <cstdlib>
13	#include <cstdint>
14	
15	#include "VUserMain0.h"
16	#include "vuserutils.h"
17	
18	// ---------------------------------------------
19	// CONSTANTS
20	// ---------------------------------------------
21	
22	// I'm VProc node 0
23	const  int             node            = 0;
24	
25	const  uint32_t        uart0_base_addr = 0x80000000;
26	const  uint32_t        sw_irq_addr     = 0xafffffff;
27	const  uint32_t        max_sync_diff   = 1000;
28	
29	// ---------------------------------------------
30	// LOCAL STATICS
31	// ---------------------------------------------
32	
33	static uint32_t        extirq          = 0;
34	static uint32_t        swirq           = 0;
35	
36	static rv32*           pCpu;
37	
38	static vusermain_cfg_t vcfg;
39	static rv32_cache*     icache          = NULL;
40	
41	static double          tv_diff_usec;
42	
43	#if (!(defined _WIN32) && !(defined _WIN64))
44	static struct          timeval tv_start, tv_stop;
45	#else
46	LARGE_INTEGER          freq, start, stop;
47	#endif
48	
49	// ---------------------------------------------
50	// Forward declarations
51	// ---------------------------------------------
52	
53	int      ext_mem_access     (const uint32_t addr, uint32_t& data, const int type, const rv32i_time_t time);
54	int      vproc_irq_callback (int val);
55	uint32_t iss_int_callback   (const rv32i_time_t time, rv32i_time_t *wakeup_time);
56	
57	// ---------------------------------------------
58	// Set up actions prior to running CPU
59	// ---------------------------------------------
60	
61	static void pre_run_setup(rv32* pCpu)
62	{
63	
64	    // Register the ISS external memory callback function
65	    pCpu->register_ext_mem_callback(ext_mem_access);
66	
67	    // Register ISS interrupt callback
68	    pCpu->register_int_callback(iss_int_callback);
69	
70	    // Register the VProc IRQ callback, used to update irq status from HDL
71	    VRegIrq(vproc_irq_callback, node);
72	
73	    // Set up ICACHE if enabled
74	    if (vcfg.enable_icache)
75	    {
76	        icache = new rv32_cache(vcfg.icache_line_bytes,
77	                                vcfg.icache_ways,
78	                                vcfg.icache_sets,
79	                                vcfg.icache_base_addr,
80	                                vcfg.icache_top_addr);
81	    }
82	
83	    // Configure the ISS timing model
84	    rv32_timing_config rv32_time_cfg;
85	
86	    // Update the ISS with the selected core's timing. Choose one of:
87	    //    rv32_timing_config::risc_v_core_e::DEFAULT,
88	    //    rv32_timing_config::risc_v_core_e::PICORV32
89	    //    rv32_timing_config::risc_v_core_e::EDUBOS5STG2
90	    //    rv32_timing_config::risc_v_core_e::EDUBOS5STG3
91	    //    rv32_timing_config::risc_v_core_e::IBEXMULSGL
92	    //    rv32_timing_config::risc_v_core_e::IBEXMULFAST
93	    //    rv32_timing_config::risc_v_core_e::IBEXMULSLOW
94	    //
95	    // See rv32_timing_config.h for supported timing models
96	    //
97	    rv32_time_cfg.update_timing(pCpu, vcfg.riscv_core);
98	
99	    // Initialise time
100	#if (!(defined _WIN32) && !(defined _WIN64)) || defined __CYGWIN__
101	    // For non-windows systems, turn off echoing of input key presses
102	    struct termios t;
103	
104	    tcgetattr(STDIN_FILENO, &t);
105	    t.c_lflag &= ~ECHO;
106	    tcsetattr(STDIN_FILENO, TCSANOW, &t);
107	
108	    // Log time just before running (LINUX only)
109	    (void)gettimeofday(&tv_start, NULL);
110	#else
111	
112	    QueryPerformanceFrequency(&freq);
113	    QueryPerformanceCounter(&start);
114	#endif
115	}
116	
117	// ---------------------------------------------
118	// Actions to run after CPU returns from
119	// executing
120	// ---------------------------------------------
121	
122	static void post_run_actions(rv32i_cfg_s cfg)
123	{
124	    // Calculate time difference, in microseconds, from now
125	    // to previously saved time stamp
126	#if (!(defined _WIN32) && !(defined _WIN64))
127	    // For non-windows systems, turn off echoing of input key presses
128	    struct termios t;
129	
130	    tcgetattr(STDIN_FILENO, &t);
131	    t.c_lflag |= ECHO;
132	    tcsetattr(STDIN_FILENO, TCSANOW, &t);
133	
134	    // Get time just after running, and calculate run time (LINUX only)
135	    (void)gettimeofday(&tv_stop, NULL);
136	    tv_diff_usec = ((float)(tv_stop.tv_sec - tv_start.tv_sec)*1e6) + ((float)(tv_stop.tv_usec - tv_start.tv_usec));
137	#else
138	    QueryPerformanceCounter(&stop);
139	    tv_diff_usec = (double)(stop.QuadPart - start.QuadPart)*1e6/(double)freq.QuadPart;
140	#endif
141	
142	    if (cfg.dump_regs)
143	    {
144	        reg_dump(pCpu, cfg.dbg_fp, cfg.abi_en);
145	    }
146	
147	    if (cfg.dump_csrs)
148	    {
149	        csr_dump(pCpu, cfg.dbg_fp);
150	    }
151	
152	    if (cfg.num_instr != 0)
153	    {
154	        VPrint("\nNumber of executed instructions = %.1f million (%.0f IPS)\n\n",
155	               (float)cfg.num_instr/1e6, (float)cfg.num_instr/(tv_diff_usec/1e6));
156	    }
157	}
158	
159	// ---------------------------------------------
160	// External memory map access callback function
161	// ---------------------------------------------
162	
163	int ext_mem_access (const uint32_t addr, uint32_t& data, const int type, const rv32i_time_t time)
164	{
165	    const int       write_wait_cycle      = 0;
166	    const int       read_data_wait_cycle  = 1;
167	    const int       read_instr_wait_cycle = 1;
168	    bool            access_sim            = false;
169	    int             processed             = RV32I_EXT_MEM_NOT_PROCESSED;
170	    uint64_t        curr_cycles;
171	    uint32_t        cycle_diff;
172	    static uint64_t last_cycles           = 0;
173	
174	    // Select whether making simulation or direct memory model access
175	    access_sim  = addr >= vcfg.ext_access_base_addr && addr < vcfg.ext_access_top_addr;
176	
177	    // -------------------------------------------
178	    // Synchronise ISS time and simulation time
179	    // -------------------------------------------
180	    curr_cycles = pCpu->clk_cycles();
181	    cycle_diff  = (uint32_t)(curr_cycles - last_cycles);
182	
183	    // Force synchronisation of simulation when reading instructions and the
184	    // ISS/sim skew reaches a limit to minimise simulation interaction when
185	    // no load/stores for a while.
186	    if (!access_sim)
187	    {
188	        if ((type & MEM_NOT_DBG_MASK) == MEM_RD_ACCESS_INSTR && cycle_diff >= max_sync_diff)
189	        {
190	            VTick(cycle_diff, node);
191	            last_cycles = curr_cycles;
192	        }
193	    }
194	    // Synchronise CPU time with simulation at simulation access load or store
195	    else
196	    {
197	        VTick(cycle_diff, node);
198	        last_cycles = curr_cycles;
199	    }
200	
201	    // -------------------------------------------
202	    // Make memory access
203	    // -------------------------------------------
204	
205	    // Accessing the software interrupt
206	    if (addr == sw_irq_addr)
207	    {
208	        swirq     = (data & 0x1) << 2;
209	        processed = write_wait_cycle;
210	    }
211	    else if ((processed = uart_reg_access(addr, data, type, uart0_base_addr)) == RV32I_EXT_MEM_NOT_PROCESSED)
212	    {
213	        // Do access
214	        switch (type & MEM_NOT_DBG_MASK)
215	        {
216	        case MEM_RD_ACCESS_BYTE:
217	            data      = read_byte(addr, access_sim);
218	            processed = read_data_wait_cycle;
219	            break;
220	        case MEM_RD_ACCESS_HWORD:
221	            data      = read_hword(addr, access_sim);
222	            processed = read_data_wait_cycle;
223	            break;
224	        case MEM_RD_ACCESS_INSTR:
225	            data      = read_instr(addr, access_sim);
226	            processed = read_instr_wait_cycle;
227	
228	            // Process caching if enabled
229	            if (vcfg.enable_icache)
230	            {
231	                // Add wait states for icache miss
232	                if (icache->rv32_cache_access(addr) == RV32_CACHE_MISS)
233	                {
234	                    // Additional wait states is the access time to slow memory times the number
235	                    // of words fetched to fill the line.
236	                    processed += vcfg.penalty_slow_mem * icache->get_line_width()/4;
237	                }
238	            }
239	            break;
240	        case MEM_RD_ACCESS_WORD:
241	            data      = read_word(addr, access_sim);
242	            processed = read_data_wait_cycle;
243	            break;
244	        case MEM_WR_ACCESS_BYTE:
245	            write_byte(addr, data, access_sim);
246	            processed = write_wait_cycle;
247	            break;
248	        case MEM_WR_ACCESS_HWORD:
249	            write_hword(addr, data, access_sim);
250	            processed = write_wait_cycle;
251	            break;
252	        case MEM_WR_ACCESS_INSTR:
253	            // When loading instructions, always use direct memory API
254	            write_word(addr, data, 0);
255	            processed = 0;
256	            break;
257	        case MEM_WR_ACCESS_WORD:
258	            write_word(addr, data, access_sim);
259	            processed = write_wait_cycle;
260	            break;
261	        default:
262	            processed = RV32I_EXT_MEM_NOT_PROCESSED;
263	            break;
264	        }
265	    }
266	
267	    return processed;
268	}
269	
270	// ---------------------------------------------
271	// VProc interrupt callback function
272	// ---------------------------------------------
273	
274	// Note: the VProc CB function can only be active when the main thread
275	// is stalled on a read, write or tick, so it is safe to modify shared
276	// variables. Also, it is not valid to make further VProc calls from
277	// this CB, but updating state here should instigate required functionality
278	// in the main program flow.
279	int vproc_irq_callback(int val)
280	{
281	    extirq = val;
282	
283	    return 0;
284	}
285	
286	// ---------------------------------------------
287	// Load binary file to memory
288	// ---------------------------------------------
289	
290	static int read_binary(const char *exec_fname, uint32_t load_addr)
291	{
292	    int         error = 0;
293	    FILE*       bin_fp;
294	    char        buf[4];
295	    int         c;
296	    uint32_t*   word = (uint32_t*)buf;
297	    bool        fault;
298	
299	    // Open program file ready for loading
300	    if ((bin_fp = fopen(exec_fname, "rb")) == NULL)
301	    {
302	        fprintf(stderr, "*** read_binary(): Unable to open file %s for reading\n", exec_fname);
303	        return 1;
304	    }
305	
306	    for (int idx = 0; 1; idx++)
307	    {
308	        if ((c = fgetc(bin_fp)) != EOF)
309	        {
310	            buf[idx & 0x3] = c;
311	            if ((idx & 0x3) == 3)
312	            {
313	                pCpu->write_mem(load_addr + (idx & ~0x3U), *word, MEM_WR_ACCESS_INSTR, fault);
314	            }
315	        }
316	        else
317	        {
318	            // Flush partial words
319	            if (idx & 0x3)
320	            {
321	                pCpu->write_mem(load_addr + (idx & ~0x3U), *word & ((1 << (load_addr & 0x3)*8)-1), MEM_WR_ACCESS_INSTR, fault);
322	            }
323	
324	            // Exit loop
325	            break;
326	        }
327	    }
328	
329	    return 0;
330	}
331	
332	// ---------------------------------------------
333	// ISS interrupt callback function
334	// ---------------------------------------------
335	
336	// The ISS interrupt callback will return an interrupt when IRQs
337	// non-zero, else it returns 0. The wakeup time in this model is always the next
338	// cycle.
339	uint32_t iss_int_callback(const rv32i_time_t time, rv32i_time_t *wakeup_time)
340	{
341	    bool terminate;
342	
343	    *wakeup_time = time + 1;
344	
345	    bool uart_irq = uart_tick(time, terminate);
346	
347	    return extirq | swirq | (uart_irq ? 1 : 0);
348	}
349	
350	// =============================================
351	// Main entry point for VProc node 0
352	// =============================================
353	
354	extern "C" void VUserMain0()
355	{
356	    rv32i_cfg_s   cfg;
357	    int error = 0;
358	
359	    VPrint("\n  ******************************\n");
360	    VPrint(  "  *   Wyvern Semiconductors    *\n");
361	    VPrint(  "  * rv32 RISC-V ISS (on VProc) *\n");
362	    VPrint(  "  *     Copyright (c) 2025     *\n");
363	    VPrint(  "  ******************************\n\n");
364	
365	    VTick(20, node);
366	
367	    // Parse arguments. As no argc and argv, pass in these as null, and it will look for
368	    // vusermain.cfg, which should have a single line with the command line options. If this
369	    // doesn't exist, no parsing is done.
370	    if (parseArgs(0, NULL, cfg, vcfg, node))
371	    {
372	        VPrint("***Error in parsing args. ISS not run.\n");
373	    }
374	    else
375	    {
376	        // Create the top level rv32 ISS cpu object
377	        pCpu = new rv32(cfg.dbg_fp);
378	
379	        // Configure the ISS and other setups before running
380	        pre_run_setup(pCpu);
381	
382	        // If GDB mode selected, pass execution to the remote GDB interface
383	        if (cfg.gdb_mode)
384	        {
385	
386	            // Set to halt on ebreak when in gdb mode
387	            cfg.hlt_on_ebreak = true;
388	
389	            // Load an executable if specified on the command line
390	            if (cfg.user_fname)
391	            {
392	                if (!vcfg.load_binary)
393	                {
394	                    if (pCpu->read_elf(cfg.exec_fname))
395	                    {
396	                        error++;
397	                    }
398	                }
399	                else
400	                {
401	                    // Load the specified binary to memory
402	                    if (read_binary(cfg.exec_fname, vcfg.bin_load_addr))
403	                    {
404	                        error++;
405	                    }
406	                }
407	            }
408	
409	            if (!error)
410	            {
411	                // Start processing commands from GDB
412	                if (rv32gdb_process_gdb(pCpu, cfg.gdb_ip_portnum, cfg))
413	                {
414	                    fprintf(stderr, "***ERROR in opening PTY\n");
415	                    error++;
416	                }
417	            }
418	        }
419	        // Normal execution mode (not gdb debugging)
420	        else
421	        {
422	            if (!vcfg.load_binary)
423	            {
424	                // Load the specified executable to memory
425	                if (pCpu->read_elf(cfg.exec_fname))
426	                {
427	                    error++;
428	                }
429	            }
430	            else
431	            {
432	                // Load the specified binary to memory
433	                if (read_binary(cfg.exec_fname, vcfg.bin_load_addr))
434	                {
435	                    error++;
436	                }
437	            }
438	
439	            if (!error)
440	            {
441	                // Run the processor
442	                pCpu->run(cfg);
443	
444	                VPrint("Exited running %s\n", cfg.exec_fname);
445	            }
446	        }
447	
448	        // Run any actions after ISS exits
449	        post_run_actions(cfg);
450	
451	        // Clean up
452	        if (cfg.dbg_fp != stdout)
453	        {
454	            fclose(cfg.dbg_fp);
455	        }
456	        delete pCpu;
457	    }
458	
459	    // Allow the simulation to continue indefinitely.
460	    SLEEP_FOREVER;
461	}
