266	void reg_dump(rv32* pCpu, FILE* dfp, bool abi_en)
267	{
268	    fprintf(dfp, "\nRegister state:\n\n  ");
269	
270	    // Loop through all the registers
271	    for (int idx = 0; idx < rv32i_consts::RV32I_NUM_OF_REGISTERS; idx++)
272	    {
273	        // Get the appropriate mapped register name (ABI or x)
274	        const char* map_str = abi_en ? pCpu->rmap_str[idx] : pCpu->xmap_str[idx];
275	
276	        // Get the length of the register name string
277	        size_t  slen = strlen(map_str);
278	
279	        // Fetch the value of the register indexed
280	        uint32_t rval = pCpu->regi_val(idx);
281	
282	        // Print out the register name (right justified) followed by the value
283	        fprintf(dfp, "%s%s = 0x%08x ", (slen == 2) ? "  " : (slen == 3) ? " ": "",
284	                                         map_str,
285	                                         rval);
286	
287	        // After every fourth value, output a new line
288	        if ((idx % 4) == 3)
289	        {
290	            fprintf(dfp, "\n  ");
291	        }
292	    }
293	
294	    // Add a final new line
295	    fprintf(dfp, "\n");
296	}
