#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

#ifndef _VUSERMAIN0_H_
#define _VUSERMAIN0_H_

#if !defined _WIN32 && !defined _WIN64
#include <unistd.h>
#include <termios.h>
#include <sys/time.h>

#define STRDUP strdup
#else
# undef   UNICODE
# define  WIN32_LEAN_AND_MEAN

# include <windows.h>
